  .setName('ban')
  .setDescription('Ban a member from the server')
  .addStringOption(option =>
    option
      .setName('member_id')
      .setDescription('Member ID to ban')
      .setRequired(true))
  .setDefaultPermission(false)
);

// Define a handler for the ban command
