  for (const num of numbers) {
    if (isPrime(num)) {
      console.log(`Prime number found: ${num}`);
    }
  }
}

function isPrime(num) {
  if (num <= 1) return false;

  // Check if the current number is divisible by any number between 2 and its square root
  for (let i = 2; i * i <= num; i++) {
    if (num % i === 0) return false;
  }

  return true; // If the number isn't divisible by any number up to its square root, then it's a prime number
}
