Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

#include <fstream>
#include <iostream>
#include <string>

int main() {
  std::string wordToCount;    // The word to count
  std::string fileToRead;     // The file name to read
  int counter = 0;             // The counter for the word occurrences

  std::cout << "Enter the word to count: ";
  std::cin >> wordToCount;
  std::cout << "Enter the file name: ";
  std::cin >> fileToRead;

  std::ifstream inputFile(fileToRead);  // Open the file for reading
  if (!inputFile.is_open()) {
    std::cout << "Error opening the file." << std::endl;
    return 1;
  }

  std::string line;                  // A line from the file
  while (std::getline(inputFile, line)) {  // Loop until the end of the file is reached
    size_t found = line.find(wordToCount);  // Find the first occurrence of the word
    while (found != std::string::npos) {    // While the word exists in the line
      counter++;                            // Increment the counter
      found = line.find(wordToCount, found + 1);  // Find the next occurrence of the word
    }
  }

  inputFile.close();  // Close the file
  std::cout << "The word '" << wordToCount << "' occurred " << counter << " times." << std::endl;
  return 0;
}

To use this program, enter the word to count (e.g., "hello"), the name of the text file to read (e.g., "mytextfile.txt"), and press Enter. The output will report the number of occurrences of the word in the file.

Here's a C++ implementation of a function to find common elements between two arrays without using any extra data structures:

```c++
vector<int> CommonElements(const vector<int>& arr1, const vector<int>& arr2) 
{
    vector<int> common; // To store common elements

    // Traverse both the arrays simultaneously
    int i = 0, j = 0;
    while (i < arr1.size() && j < arr2.size())
    {
        if (arr1[i] == arr2[j])
        {
            common.push_back(arr1[i]);
            i++; j++;
        }
        else if (arr1[i] < arr2[j])
            i++; // Move to the next element in the first array
        else
            j++; // Move to the next element in the second array
    }

    return common;
}
```

This function takes two `std::vector` as parameters, traverses each of them simultaneously, and appends common elements into a third `std::vector` which it returns. While traversing, it checks if the current element in both arrays is the same, and if so, it stores it in the output vector. If the current element of the first array is less than the current element of the second array, it moves to the next element of the first array; otherwise, it moves to the next element of the second array. This continues until either one of the arrays is fully traversed.
